-- Foreign keys make relational reads work and prevent cross-wedding references.
create or replace function public.enforce_wedding_reference() returns trigger language plpgsql security definer set search_path='' as $$
declare target_wedding uuid; ref uuid; begin
 ref := nullif(to_jsonb(new)->>TG_ARGV[0],'')::uuid;
 if ref is null then return new; end if;
 execute format('select wedding_id from public.%I where id=$1',TG_ARGV[1]) into target_wedding using ref;
 if target_wedding is distinct from new.wedding_id then raise exception 'Invalid wedding reference' using errcode='23514'; end if; return new; end $$;
do $$ begin if not exists(select 1 from pg_constraint where contype='f' and conrelid='public.budget_activity_log'::regclass and conkey=array[(select attnum from pg_attribute where attrelid='public.budget_activity_log'::regclass and attname='wedding_id')]::smallint[]) then alter table public.budget_activity_log add constraint budget_activity_log_wedding_id_journey_fk foreign key(wedding_id) references public.weddings(id) not valid; end if; end $$;
