do $$ begin if not exists(select 1 from pg_constraint where contype='f' and conrelid='public.wedora_billing_events'::regclass and conkey=array[(select attnum from pg_attribute where attrelid='public.wedora_billing_events'::regclass and attname='wedding_id')]::smallint[]) then alter table public.wedora_billing_events add constraint wedora_billing_events_wedding_id_journey_fk foreign key(wedding_id) references public.weddings(id) not valid; end if; end $$;
