-- Extended seating and planning models use these explicit parent names.
do $$ declare r record; a smallint; constraint_name text; begin
 for r in select c.table_name,c.column_name,case c.column_name when 'seating_plan_id' then 'seating_plans' when 'background_asset_id' then 'seating_background_assets' when 'budget_id' then 'wedding_budgets' when 'registry_item_id' then 'gift_registry_items' when 'seating_plan_version_id' then 'seating_plan_versions' end as parent_table from information_schema.columns c where c.table_schema='public' and c.data_type='uuid' and c.column_name in ('seating_plan_id','background_asset_id','budget_id','registry_item_id','seating_plan_version_id') and exists(select 1 from information_schema.columns w where w.table_schema='public' and w.table_name=c.table_name and w.column_name='wedding_id') loop
  select attnum into a from pg_attribute where attrelid=('public.'||r.table_name)::regclass and attname=r.column_name;
  if not exists(select 1 from pg_constraint where contype='f' and conrelid=('public.'||r.table_name)::regclass and conkey=array[a]) then
   constraint_name:=left(r.table_name||'_'||r.column_name||'_journey_fk',63);
   execute format('alter table public.%I add constraint %I foreign key(%I) references public.%I(id) not valid',r.table_name,constraint_name,r.column_name,r.parent_table);
  end if;
  execute format('create trigger %I before insert or update of wedding_id,%I on public.%I for each row execute function public.enforce_wedding_reference(%L,%L)',left('scope_'||r.column_name,63),r.column_name,r.table_name,r.column_name,r.parent_table);
 end loop;
end $$;
